messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>Red vs Blue — Three.js Race</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background-color: #000;
      font-family: 'Arial', sans-serif;
    }
    canvas {
      display: block;
    }
    #info {
      position: absolute;
      top: 20px;
      left: 20px;
      color: white;
      background: rgba(0,0,0,0.6);
      padding: 8px 16px;
      border-radius: 8px;
      font-size: 16px;
      pointer-events: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="info">🏁 Red vs Blue — race loop</div>
  <script type="importmap">
    { "imports": { "./three.module.js": "https://threejs.org/build/three.module.js" } }
  </script>

  <script type="module">
    import * as THREE from './three.module.js';

    // --- Setup scene, camera, renderer ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x87CEEB); // sky blue

    // Ground
    const groundGeo = new THREE.PlaneGeometry(20, 30);
    const groundMat = new THREE.MeshStandardMaterial({ color: 0x4a5a3a, roughness: 0.8 });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.2;
    ground.position.z = 5; // shift track into view
    scene.add(ground);

    // Track lines (simple white stripes)
    const trackMat = new THREE.MeshBasicMaterial({ color: 0xdddddd });
    // left line
    const lineL = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.05, 30), trackMat);
    lineL.position.set(-1.2, 0.05, 5);
    scene.add(lineL);
    // right line
    const lineR = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.05, 30), trackMat);
    lineR.position.set(1.2, 0.05, 5);
    scene.add(lineR);

    // Finish line (checkered pattern simplified)
    const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const finishBase = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.1, 0.3), finishMat);
    finishBase.position.set(0, 0.1, -2.5);
    scene.add(finishBase);
    // black stripes
    const stripeMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
    for (let i = -1; i <= 1; i += 0.5) {
      const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.12, 0.31), stripeMat);
      stripe.position.set(i, 0.15, -2.5);
      scene.add(stripe);
    }
    // finish pole flags (simple)
    const poleMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
    const pole1 = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.0, 0.1), poleMat);
    pole1.position.set(-1.3, 0.5, -2.5);
    scene.add(pole1);
    const pole2 = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.0, 0.1), poleMat);
    pole2.position.set(1.3, 0.5, -2.5);
    scene.add(pole2);
    // checkered flag (small)
    const flagMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
    const flag = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.3, 0.05), flagMat);
    flag.position.set(-1.3, 1.0, -2.5);
    scene.add(flag);
    const flagBlack = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.15, 0.06), stripeMat);
    flagBlack.position.set(-1.3, 1.0, -2.5);
    scene.add(flagBlack);

    // Lighting
    const ambient = new THREE.AmbientLight(0x404060);
    scene.add(ambient);
    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 10, 7);
    scene.add(dirLight);
    const fillLight = new THREE.DirectionalLight(0x88aaff, 0.5);
    fillLight.position.set(-5, 3, 5);
    scene.add(fillLight);

    // Camera
    const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
    camera.position.set(0, 3.2, 12);
    camera.lookAt(0, 0.5, 2);

    // --- Create car meshes (simple but distinct) ---
    function createCar(color) {
      const group = new THREE.Group();

      // body
      const bodyMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.4, metalness: 0.3 });
      const body = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.4, 1.8), bodyMat);
      body.position.y = 0.25;
      body.position.z = 0;
      group.add(body);

      // cabin
      const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 });
      const cabin = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.35, 0.9), cabinMat);
      cabin.position.y = 0.55;
      cabin.position.z = -0.1;
      group.add(cabin);

      // wheels (dark cylinders)
      const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.9 });
      const wheelPositions = [
        [-0.5, 0.1, 0.6],
        [0.5, 0.1, 0.6],
        [-0.5, 0.1, -0.6],
        [0.5, 0.1, -0.6]
      ];
      wheelPositions.forEach(pos => {
        const wheelGeo = new THREE.CylinderGeometry(0.18, 0.18, 0.2, 16);
        const wheel = new THREE.Mesh(wheelGeo, wheelMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(pos[0], pos[1], pos[2]);
        group.add(wheel);
      });

      // headlights/taillights (small spheres)
      const lightMat = new THREE.MeshStandardMaterial({ color: 0xffaa33, emissive: 0x553300 });
      const headL = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8), lightMat);
      headL.position.set(-0.35, 0.3, 0.95);
      group.add(headL);
      const headR = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8), lightMat);
      headR.position.set(0.35, 0.3, 0.95);
      group.add(headR);

      // red/blue glow to make cars more visible
      const glowMat = new THREE.MeshStandardMaterial({ color: color, emissive: color, emissiveIntensity: 0.3 });
      const glow = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 8), glowMat);
      glow.position.set(0, 0.25, 0);
      glow.scale.set(1.2, 0.6, 1.8);
      group.add(glow);
      glow.visible = false; // optional, but we'll add a subtle outline via body

      return group;
    }

    const redCar = createCar(0xff2200); // bright red
    const blueCar = createCar(0x0044ff); // bright blue

    // Slightly enlarge cars for visibility
    redCar.scale.set(1.1, 1.1, 1.1);
    blueCar.scale.set(1.1, 1.1, 1.1);

    // Position cars at start
    redCar.position.set(0.6, 0.15, 8.5);
    blueCar.position.set(-0.6, 0.15, 8.5);

    scene.add(redCar);
    scene.add(blueCar);

    // Add simple shadows (optional)
    redCar.traverse((obj) => {
      if (obj.isMesh) obj.castShadow = true;
    });
    blueCar.traverse((obj) => {
      if (obj.isMesh) obj.castShadow = true;
    });
    ground.receiveShadow = true;

    // --- Race parameters ---
    const finishZ = -2.5; // finish line z position
    const startZ = 8.5;
    const trackLength = startZ - finishZ; // 11 units

    let raceTime = 0; // seconds
    let raceDuration = 6; // loop duration (seconds)
    let blueLeadTime = 1.2; // blue leads for first 1.2s
    let redBoostTime = 2.0; // red accelerates at 2.0s

    // Speed profiles (normalized 0..1 along track)
    // We'll map raceTime to progress 0->1
    // Blue: fast early, then slightly slower
    // Red: slower early, then faster after t=2

    function blueProgress(t) {
      // t in [0,1] normalized race time
      // Blue: quick start, but loses speed
      const p = t;
      // piecewise: linear until 0.25, then slower
      if (p < 0.25) {
        return p * 1.8; // reaches 0.45 at 0.25
      } else {
        // from 0.25 to 1.0, go from 0.45 to 1.0 slowly
        return 0.45 + (p - 0.25) * 0.75;
      }
    }

    function redProgress(t) {
      // Red: slow start, then fast
      const p = t;
      if (p < 0.35) {
        return p * 1.2; // reaches 0.42 at 0.35
      } else {
        // from 0.35 to 1.0, go from 0.42 to 1.0 faster
        return 0.42 + (p - 0.35) * 1.2;
      }
    }

    // To ensure overtake mid-race, we adjust profiles:
    // At t=0.5, red should be ahead.
    // Let's craft:
    // blue: 0->0.5: 0.0->0.55, 0.5->1.0: 0.55->1.0
    // red: 0->0.5: 0.0->0.5, 0.5->1.0: 0.5->1.0 (slightly faster)
    // Actually simpler: use custom functions:
    function blueNorm(t) {
      // t 0..1, returns 0..1
      // Blue leads early: at t=0.25, blue=0.35, red=0.2
      // at t=0.5, blue=0.55, red=0.5 (red overtakes after 0.5)
      // at t=1, both 1
      if (t < 0.25) return t * 1.4; // 0..0.35
      if (t < 0.5) return 0.35 + (t - 0.25) * 0.8; // 0.35..0.55
      return 0.55 + (t - 0.5) * 0.9; // 0.55..1.0
    }

    function redNorm(t) {
      // Red slower early, then faster
      if (t < 0.25) return t * 0.8; // 0..0.2
      if (t < 0.5) return 0.2 + (t - 0.25) * 1.2; // 0.2..0.5
      return 0.5 + (t - 0.5) * 1.0; // 0.5..1.0 (slightly slower than blue? but overtake)
    }

    // At t=0.5 both ~0.5, but red accelerates faster after 0.25 so it reaches 0.5 at t=0.5, blue also 0.5. Let's make red overtake after 0.45:
    // red: 0.25->0.5: 0.2->0.55 (faster)
    // blue: 0.25->0.5: 0.35->0.55 (slower)
    // So red overtakes around 0.45.

    function blueNorm2(t) {
      if (t < 0.25) return t * 1.4; // 0..0.35
      if (t < 0.5) return 0.35 + (t - 0.25) * 0.8; // 0.35..0.55
      return 0.55 + (t - 0.5) * 0.9; // 0.55..1.0
    }

    function redNorm2(t) {
      if (t < 0.25) return t * 0.8; // 0..0.2
      if (t < 0.5) return 0.2 + (t - 0.25) * 1.4; // 0.2..0.55 (overtake!)
      return 0.55 + (t - 0.5) * 0.9; // 0.55..1.0
    }

    // Use these for animation
    const blueProg = blueNorm2;
    const redProg = redNorm2;

    // --- Animation loop ---
    let clock = new THREE.Clock();

    function animate() {
      const delta = clock.getDelta();
      raceTime += delta;

      // Loop race
      if (raceTime > raceDuration) {
        raceTime = 0;
      }

      const t = raceTime / raceDuration; // 0..1

      // Compute z positions
      const blueZ = finishZ + (startZ - finishZ) * (1 - blueProg(t));
      const redZ = finishZ + (startZ - finishZ) * (1 - redProg(t));

      // Set car positions (x offset for lane)
      blueCar.position.z = blueZ;
      redCar.position.z = redZ;

      // Slight tilt / rotation for motion feel
      blueCar.rotation.x = Math.sin(t * 20) * 0.02;
      redCar.rotation.x = Math.sin(t * 20 + 0.5) * 0.02;

      // Camera: keep both cars in view
      // Position camera behind and above, look at midpoint
      const midZ = (blueZ + redZ) / 2;
      camera.position.set(0, 3.0 + Math.sin(t * 5) * 0.2, 10 + (midZ - 3) * 0.3);
      camera.lookAt(0, 0.5, midZ + 1);

      // Render
      renderer.render(scene, camera);

      requestAnimationFrame(animate);
    }

    // --- Renderer setup ---
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Handle resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Start animation
    animate();

    // --- Additional decorative elements ---
    // Add some clouds / simple sky objects
    const cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0x222222, roughness: 0.9 });
    for (let i = 0; i < 6; i++) {
      const cloud = new THREE.Mesh(new THREE.SphereGeometry(0.4, 8, 8), cloudMat);
      cloud.position.set((Math.random() - 0.5) * 8, 3 + Math.random() * 2, 2 + Math.random() * 5);
      cloud.scale.set(1.5, 0.6, 0.8);
      scene.add(cloud);
    }

    // Start line (slightly behind)
    const startMat = new THREE.MeshStandardMaterial({ color: 0xcccccc });
    const startLine = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.08, 0.2), startMat);
    startLine.position.set(0, 0.1, 8.5);
    scene.add(startLine);

    // Distance markers
    const markerMat = new THREE.MeshStandardMaterial({ color: 0xffaa00 });
    for (let z = 5; z >= -2; z -= 2) {
      const marker = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.2, 0.2), markerMat);
      marker.position.set(0, 0.2, z);
      scene.add(marker);
    }

    // Ensure cars are visible with emissive outlines? We'll add a subtle glow via body color.
    // Already body colors are bright.

    // Small dust particles? skip.

    // Add a few trees? no.

    console.log('Race scene ready!');
  </script>
</body>
</html>
```
